import { test, expect } from 'bun:test';
import { itemCount, orderTotal } from '../src/cart.js';
test('item count', () => expect(itemCount([{ priceCents: 100, qty: 2 }, { priceCents: 5, qty: 1 }])).toBe(3));
test('total without tax', () => expect(orderTotal([{ priceCents: 1999, qty: 3 }], 0)).toBe(5997));
test('total with tax', () => expect(orderTotal([{ priceCents: 1000, qty: 2 }], 10)).toBe(2200));
test('empty cart', () => expect(orderTotal([], 8)).toBe(0));

