import { test, expect } from 'bun:test';
import { orderTotal } from '../src/cart.js';
test('half cents round up exactly', () => {
  expect(orderTotal([{ priceCents: 50, qty: 1 }], 15)).toBe(58);
  expect(orderTotal([{ priceCents: 90, qty: 1 }], 15)).toBe(104);
  expect(orderTotal([{ priceCents: 100, qty: 1 }], 0.5)).toBe(101);
});
test('negative or fractional amounts are rejected', () => {
  expect(() => orderTotal([{ priceCents: -500, qty: 1 }], 0)).toThrow();
  expect(() => orderTotal([{ priceCents: 500, qty: -1 }], 0)).toThrow();
  expect(() => orderTotal([{ priceCents: 19.99, qty: 1 }], 0)).toThrow();
  expect(() => orderTotal([{ priceCents: 500, qty: 1 }], -5)).toThrow();
});
